-- Load the dual-monitor modules only while the Dell LCD is connected.
require("custom.display_profile")

-- Restore the current wallpaper on any display missing it after login, an
-- output connecting or its profile reloading. Displays already showing it are
-- left alone, so login does not restart the transition several times.
-- Debounce monitor changes so the LCD's mode and scale have time to settle.
local wallpaperRestoreTimer
local function scheduleWallpaperRestore()
    if wallpaperRestoreTimer then
        wallpaperRestoreTimer:set_timeout(1000)
    else
        wallpaperRestoreTimer = hl.timer(function()
            wallpaperRestoreTimer = nil
            hl.exec_cmd(os.getenv("HOME") .. "/.config/hypr/custom/restore-wallpaper.sh")
        end, { timeout = 1000, type = "oneshot" })
    end
end
hl.on("hyprland.start", scheduleWallpaperRestore)
hl.on("monitor.added", scheduleWallpaperRestore)
hl.on("config.reloaded", scheduleWallpaperRestore)

